-- Meeting: contact, phone, place name, address (map) and link, as in Tactify. Only when the type still has the original fields.
UPDATE {p}task_types SET fields = '[{"key":"contact_id","kind":"contact","label":"Contact","label_ru":"Контакт"},{"key":"phone","kind":"phone","label":"Phone","label_ru":"Телефон"},{"key":"place","kind":"text","label":"Place name","label_ru":"Название места"},{"key":"address","kind":"text","label":"Address","label_ru":"Адрес"},{"key":"link","kind":"url","label":"Link","label_ru":"Ссылка"}]' WHERE code = 'meeting' AND fields = '[{"key":"place","kind":"text","label":"Place","label_ru":"Место"},{"key":"link","kind":"url","label":"Link","label_ru":"Ссылка"}]';
